/* From Uiverse.io by NabeelAhmadK - Tags: button */
.__UIV_SCOPE__ button {
  width: fit-content;
  height: 45px;
  background: #ffffff0d;
  border-radius: 8px;
  border: 2px solid #334b79;
  font-size: 15px;
  font-weight: bold;
  color: #334b79;
  -webkit-transition: 0.5s all ease;
  transition: 0.5s all ease;
  position: relative;
  overflow: hidden;
  padding: 10px 25px;
  z-index: 1;
}

.__UIV_SCOPE__ button:before {
  width: 50%;
  height: 100%;
  content: "";
  margin: auto;
  position: absolute;
  top: 0%;
  left: -50%;
  background: #334b79;
  transition: all 0.5s ease;
  z-index: -1;
}

.__UIV_SCOPE__ button:after {
  width: 50%;
  height: 100%;
  content: "";
  margin: auto;
  position: absolute;
  top: 0%;
  left: 100%;
  background: #334b79;
  transition: all 0.5s ease;
  z-index: -1;
}

.__UIV_SCOPE__ button:hover {
  color: white;
  cursor: pointer;
}

.__UIV_SCOPE__ button:hover:before {
  top: 0;
  left: 0;
}

.__UIV_SCOPE__ button:hover:after {
  top: 0;
  left: 50%;
}
